head.script:

    // >= ie9  
	// Function : init 
    scwin.init = function(){
    	handler_horizontal.setUserData("resizable" , false );
    	$w.local.setItem('initGrid', grid1.getGridStyle());
    	//console.log(grid1.getGridStyle());
    	scwin.btn_pimport_onclick();

    };



    //------------------------------------
	// USE THE RESIZE HANDLER
	//------------------------------------
	scwin.handler_horizontal_onmousedown = function(e) {
		handler_horizontal.setUserData("resizable" , true );	
	};

	document.onmousemove = function(e) {
		var resizable = handler_horizontal.getUserData("resizable");
		if( resizable ){ 
			var resizeGrp = WebSquare.util.getComponentById( "resize_grp" );

			// 0. $("#resize_grp").offset().top ??? -> padding info.
			// if vertical scrollbar is visible in browser, you need to consider the scrollTop.  
			resize_grp.setSize(null,  e.clientY- $("#resize_grp").offset().top );   
		}
	};


	document.onmouseup = function(e) {
		handler_horizontal.setUserData("resizable" , false );
	};
	//------------------------------------

	document.onclick = function(e){
		contextmenu.hide();
	};

	document.onselectstart =  function (e) {
		// prevent the selection. 
		return false;
	};    



