	//------------------------------------
	// MAKE THE PERSONAL CUSTOM GRID
	//------------------------------------
	scwin.btn_pexport_onclick = function()  {//debugger;
		// ** 
		// 1. when column moved without existing data in grid, error logs appear.
		var grdDoc = WebSquare.xml.parse(grid1.getCurrentGridStyle(), true);
		// getCurrentGridStyle API applies in (columnResize, columnMove, fixedColumn, hiddenColumn). 

		// 2. fixedRow property do not exist. add to grid xml document. 
		/*
		WebSquare.xml.setAttribute(grdDoc, 'fixedRow', grid1.getFixedRow() );
		var cnt = grid1.getColumnCount();
		var i = 0;
		var rowNumVisible = grid1.options.rowNumVisible;
		var rowStatusVisible = grid1.options.rowStatusVisible;
		if( rowNumVisible == true && rowStatusVisible != true ){ i = 1; }
		else if( rowNumVisible != true && rowStatusVisible == true ){ i = 1; }
		else if( rowNumVisible == true && rowStatusVisible == true ){ i = 2; }
		*/
		/*
		for( var idx=0 ; idx < cnt ; idx++){
			var width = grid1.getColumnWidth(idx+i);
			var headerID = grid1.getHeaderID(idx);
			// 3. column informations(move and width) are not synchronized in getCurrentGridStyle API.
			WebSquare.xml.setAttribute(grdDoc, '/w2:header/w2:row/w2:column[@id="'+headerID+'"]' , 'width', width ); 
		}
		*/
		$w.local.setItem('currGrid', WebSquare.xml.serialize(grdDoc));
	};


	scwin.btn_pimport_onclick = function() {//debugger;
		//dataList1.setData([]);
		grid1.initGrid();
		if( !!$w.local.getItem('currGrid')){
			grid1.setGridStyle(WebSquare.xml.parse($w.local.getItem('currGrid'), true));
		}
		scwin.btn_sch_onclick();
	};


	scwin.btn_pinit_onclick = function() {
		//dataList1.setData([]);
		grid1.setGridStyle(WebSquare.xml.parse($w.local.getItem('initGrid'), true));
	};

	//------------------------------------




	//------------------------------------
	// USE THE CONTEXT MENU
	//------------------------------------ 
	scwin.grid1_onrightbuttonclick = function(row, col, e) {
		hiddenColGrp.hide();
		contextmenu.show('');
		contextmenu.setPosition(e.clientX, e.clientY);
	};


	scwin.item1_onclick = function(e) {
		// 세로 틀고정.
		grid1.setFixedRow(grid1.getFocusedRowIndex());
	};

	scwin.item2_onclick = function(e) {
		// 세로 틀고정 해제.
		grid1.setFixedRow(0);
	};

	scwin.item3_onclick = function(e) {
		// 가로 틀고정.
		// 4. how to coding with the column index information when column moved ?????  
		grid1.setFixedColumn(grid1.getColumnOrder().indexOf(grid1.getFocusedColumnIndex()));
	};

	scwin.item4_onclick = function(e) {
		// 가로 틀고정 해제.
		grid1.setFixedColumn(0);
	};

	scwin.item5_onclick = function(e) { 
		// 컬럼 숨김.
		grid1.setColumnVisible( grid1.getFocusedColumnIndex() , false );
	};

	scwin.item6_onclick = function(e) {
		// 전체 컬럼 숨김 해제.
		var i = 0;
		var rowNumVisible = grid1.options.rowNumVisible;
		var rowStatusVisible = grid1.options.rowStatusVisible;
		if( rowNumVisible == true && rowStatusVisible != true ){ i = 1; }
		else if( rowNumVisible != true && rowStatusVisible == true ){ i = 1; }
		else if( rowNumVisible == true && rowStatusVisible == true ){ i = 2; }

		var arr = grid1.hiddenList;
		for(var idx=i; idx< arr.length; idx++){
			if( arr[idx] == true) {
				var hiddenIdx = grid1.getColumnOrder()[idx-i];

				grid1.setColumnVisible(hiddenIdx , true);

				// remove object(WebSquare.util.dynamicCreate) in context menu list.
				var id = WebSquare.util.getComponentById( "item6_" + hiddenIdx );
				if(!!id){
					id.remove();
				}
			}
		}
	};



	scwin.item6_onmouseover = function(e) {
		// 선택 컬럼 숨김 해제.
		var i = 0;
		var rowNumVisible = grid1.options.rowNumVisible;
		var rowStatusVisible = grid1.options.rowStatusVisible;
		if( rowNumVisible == true && rowStatusVisible != true ){ i = 1; }
		else if( rowNumVisible != true && rowStatusVisible == true ){ i = 1; }
		else if( rowNumVisible == true && rowStatusVisible == true ){ i = 2; }

		var arr = grid1.hiddenList;
		var cnt =0; 
		for(var idx=i; idx< arr.length; idx++){
			if( arr[idx] == true) {
				cnt++;
				var hiddenIdx = grid1.getColumnOrder()[idx-i];
				var headerIdArr = grid1.getHeaderIDArr(idx-i);
				var headerValue = grid1.getHeaderValue(headerIdArr[0]);

				var id = WebSquare.util.getComponentById( "item6_" + hiddenIdx );

				if(!id){
					// create the dynamic websquare object.
					WebSquare.util.dynamicCreate(
						"item6_" + hiddenIdx, /* string : 컴포넌트의 id */
						"textbox", /* string : 생성될 컴포넌트의 종류 */
						{
							className: "item"
							,style: ""
							,label: headerValue

						}, /* object : 컴포넌트에 적용될 attribute 값*/
						hiddenColGrp //생성할 object의 부모
					);
					var id = WebSquare.util.getComponentById( "item6_" + hiddenIdx );
					// create the dynamic event.
					id.bind("onclick", function(e){ 
						var colIdx = parseInt(this.getID().split("_")[1]);
						grid1.setColumnVisible(colIdx , true); 
						this.remove();
					}); 
				}
			}
		}
		if( cnt > 0 ){
			hiddenColGrp.show('');
		}

	};


	scwin.item6_onmouseout = function(e) {
		hiddenColGrp.hide();
	};

	scwin.hiddenColGrp_onmouseover = function(e) {
		hiddenColGrp.show('');
	};

	scwin.hiddenColGrp_onmouseout = function(e) {
		hiddenColGrp.hide();
	};


	scwin.init();
